Core Templates

Template 1  Opposite-Direction Pointers
int left = 0;
int right = nums.size() - 1;
while (left < right) {
// process nums[left] and nums[right]
left++;
right--;
}
Used for:

reverse

palindrome

inward comparison
Template 2  Sorted Two Sum
int left = 0;
int right = nums.size() - 1;
while (left < right) {
int sum = nums[left] + nums[right];
if (sum == target) {
return {left, right};
} else if (sum < target) {
left++;
} else {
right--;
}
}
Template 3  Palindrome Check
bool isPalindrome(string s) {
int left = 0;
int right = s.size() - 1;
while (left < right) {
if (s[left] != s[right]) {
return false;
}

left++;
right--;
}
return true;
}
Template 4  Reverse Array/String
int left = 0;
int right = nums.size() - 1;
while (left < right) {
swap(nums[left], nums[right]);
left++;
right--;
}
Template 5  Read/Write Pointer
int write = 0;
for (int read = 0; read < nums.size(); read++) {
if (/* keep nums[read] */) {
nums[write] = nums[read];
write++;
}
}
return write;
Template 6  Remove Duplicates from Sorted Array
if (nums.empty()) {
return 0;
}
int write = 1;
for (int read = 1; read < nums.size(); read++) {
if (nums[read] != nums[write - 1]) {
nums[write] = nums[read];
write++;

}
}
return write;
Template 7  Fixed Index + Two Pointers
sort(nums.begin(), nums.end());
for (int i = 0; i < nums.size(); i++) {
if (i > 0 && nums[i] == nums[i - 1]) {
continue;
}
int left = i + 1;
int right = nums.size() - 1;
while (left < right) {
int sum = nums[i] + nums[left] + nums[right];
if (sum == target) {
// store answer
left++;
right--;
while (left < right && nums[left] == nums[left - 1]) {
left++;
}
while (left < right && nums[right] == nums[right + 1]) {
right--;
}
} else if (sum < target) {
left++;
} else {
right--;
}
}
}
