3Sum

4Sum

3Sum Closest
Template 8  Fill Result From End
Used when the largest answer comes from either end.
vector<int> result(nums.size());
int left = 0;
int right = nums.size() - 1;
int pos = nums.size() - 1;
while (left <= right) {
if (abs(nums[left]) > abs(nums[right])) {
result[pos] = nums[left] * nums[left];
left++;
} else {
result[pos] = nums[right] * nums[right];
right--;
}
pos--;
}
