Core Templates
Template 1  Exact Binary Search
Use when you need to find target or return -1.
int binarySearch(vector<int>& nums, int target) {
int left = 0;
int right = (int)nums.size() - 1;
while (left <= right) {
int mid = left + (right - left) / 2;
if (nums[mid] == target) {
return mid;
} else if (nums[mid] < target) {
left = mid + 1;
} else {
right = mid - 1;
}
}
return -1;
}
Template 2  Lower Bound
First index where:
nums[i] >= target

int lowerBound(vector<int>& nums, int target) {
int left = 0;
int right = nums.size();
while (left < right) {
int mid = left + (right - left) / 2;
if (nums[mid] < target) {
left = mid + 1;
} else {
right = mid;
}
}
return left;
}
Return can be nums.size().
Template 3  Upper Bound
First index where:
nums[i] > target
int upperBound(vector<int>& nums, int target) {
int left = 0;
int right = nums.size();
while (left < right) {
int mid = left + (right - left) / 2;
if (nums[mid] <= target) {
left = mid + 1;
} else {
right = mid;
}
}
return left;
}
Template 4  First Occurrence
int firstOccurrence(vector<int>& nums, int target) {
int left = 0;

int right = nums.size() - 1;
int answer = -1;
while (left <= right) {
int mid = left + (right - left) / 2;
if (nums[mid] >= target) {
if (nums[mid] == target) {
answer = mid;
}
right = mid - 1;
} else {
left = mid + 1;
}
}
return answer;
}
Template 5  Last Occurrence
int lastOccurrence(vector<int>& nums, int target) {
int left = 0;
int right = nums.size() - 1;
int answer = -1;
while (left <= right) {
int mid = left + (right - left) / 2;
if (nums[mid] <= target) {
if (nums[mid] == target) {
answer = mid;
}
left = mid + 1;
} else {
right = mid - 1;
}
}
return answer;
}

Template 6  First True
For pattern:
false false false true true true
int firstTrue(int n) {
int left = 0;
int right = n - 1;
int answer = -1;
while (left <= right) {
int mid = left + (right - left) / 2;
if (condition(mid)) {
answer = mid;
right = mid - 1;
} else {
left = mid + 1;
}
}
return answer;
}
Template 7  Last True
For pattern:
true true true false false false
int lastTrue(int n) {
int left = 0;
int right = n - 1;
int answer = -1;
while (left <= right) {
int mid = left + (right - left) / 2;
if (condition(mid)) {
answer = mid;
left = mid + 1;
} else {
right = mid - 1;
}
}

return answer;
}
Template 8  Rotated Sorted Array Search
int searchRotated(vector<int>& nums, int target) {
int left = 0;
int right = nums.size() - 1;
while (left <= right) {
int mid = left + (right - left) / 2;
if (nums[mid] == target) {
return mid;
}
if (nums[left] <= nums[mid]) {
if (nums[left] <= target && target < nums[mid]) {
right = mid - 1;
} else {
left = mid + 1;
}
} else {
if (nums[mid] < target && target <= nums[right]) {
left = mid + 1;
} else {
right = mid - 1;
}
}
}
return -1;
}
Template 9  Find Minimum in Rotated Sorted Array
int findMin(vector<int>& nums) {
int left = 0;
int right = nums.size() - 1;
while (left < right) {
int mid = left + (right - left) / 2;

if (nums[mid] > nums[right]) {
left = mid + 1;
} else {
right = mid;
}
}
return nums[left];
}
Template 10  Search 2D Matrix as Flattened Array
bool searchMatrix(vector<vector<int>>& matrix, int target) {
int rows = matrix.size();
int cols = matrix[0].size();
int left = 0;
int right = rows * cols - 1;
while (left <= right) {
int mid = left + (right - left) / 2;
int r = mid / cols;
int c = mid % cols;
if (matrix[r][c] == target) {
return true;
} else if (matrix[r][c] < target) {
left = mid + 1;
} else {
right = mid - 1;
}
}
return false;
}

