pdfNotes.templates:
Core Templates
Template 1  Lomuto Partition Ascending
This places pivot in final sorted ascending position.
int partition(vector<int>& nums, int left, int right) {
int pivot = nums[right];
int store = left;
for (int i = left; i < right; i++) {
if (nums[i] <= pivot) {
swap(nums[store], nums[i]);
store++;
}
}
swap(nums[store], nums[right]);
return store;
}
After partition:
nums[left ... store-1] <= pivot
nums[store] = pivot
nums[store+1 ... right] > pivot
Template 2  Randomized Partition
int partition(vector<int>& nums, int left, int right) {
int pivotIndex = left + rand() % (right - left + 1);
swap(nums[pivotIndex], nums[right]);

int pivot = nums[right];
int store = left;
for (int i = left; i < right; i++) {
if (nums[i] <= pivot) {
swap(nums[store], nums[i]);
store++;
}
}
swap(nums[store], nums[right]);
return store;
}
Template 3  Quickselect by Target Index
int quickselect(vector<int>& nums, int targetIndex) {
int left = 0;
int right = nums.size() - 1;
while (left <= right) {
int pivotIndex = partition(nums, left, right);
if (pivotIndex == targetIndex) {
return nums[pivotIndex];
} else if (pivotIndex < targetIndex) {
left = pivotIndex + 1;
} else {
right = pivotIndex - 1;
}
}
return -1;
}
Template 4  K-th Largest
int findKthLargest(vector<int>& nums, int k) {
int n = nums.size();
int targetIndex = n - k;

return quickselect(nums, targetIndex);
}
Template 5  K-th Smallest
int findKthSmallest(vector<int>& nums, int k) {
int targetIndex = k - 1;
return quickselect(nums, targetIndex);
}
Template 6  Quickselect With Custom Score
For points, compare by distance.
int distance(vector<int>& p) {
return p[0] * p[0] + p[1] * p[1];
}
int partition(vector<vector<int>>& points, int left, int right) {
int pivotIndex = left + rand() % (right - left + 1);
swap(points[pivotIndex], points[right]);
int pivotDist = distance(points[right]);
int store = left;
for (int i = left; i < right; i++) {
if (distance(points[i]) <= pivotDist) {
swap(points[store], points[i]);
store++;
}
}
swap(points[store], points[right]);
return store;
}

