Template 2  Iterative DFS With Stack
void dfsIterative(int start, vector<vector<int>>& graph, vector<bool>& visited) {
stack<int> st;
st.push(start);
visited[start] = true;
while (!st.empty()) {
int node = st.top();
st.pop();
for (int neighbor : graph[node]) {
if (!visited[neighbor]) {
visited[neighbor] = true;
st.push(neighbor);
}

}
}
}
