vector<vector<int>>& graph,
vector<bool>& visited) {
if (node == target) {
return true;
}
visited[node] = true;
for (int neighbor : graph[node]) {
if (!visited[neighbor]) {
if (dfs(neighbor, target, graph, visited)) {
return true;
}
}
}
return false;
