Template 5  Grid DFS
void dfs(vector<vector<char>>& grid, int r, int c) {
int rows = grid.size();
int cols = grid[0].size();
if (r < 0 || c < 0 || r >= rows || c >= cols) {
return;
}
if (grid[r][c] != '1') {
return;
}
grid[r][c] = '0';
dfs(grid, r + 1, c);
dfs(grid, r - 1, c);
dfs(grid, r, c + 1);
dfs(grid, r, c - 1);
}
Template 6  DFS With Path Backtracking
void dfs(int node,
int target,
vector<vector<int>>& graph,
vector<int>& path,
vector<vector<int>>& result) {
if (node == target) {
result.push_back(path);
return;
}
for (int neighbor : graph[node]) {
path.push_back(neighbor);
dfs(neighbor, target, graph, path, result);
path.pop_back();
}
}
Used for DAG path generation.

Template 7  Directed Graph Cycle Detection
