if (state[node] == 1) {
return true;
}
if (state[node] == 2) {
return false;
}
state[node] = 1;
for (int neighbor : graph[node]) {
if (dfs(neighbor, graph, state)) {
return true;
}
}
state[node] = 2;
return false;
}
State meanings:
0 = unvisited
1 = visiting, currently in recursion stack
2 = done
