0 = unvisited
1 = visiting
2 = done
11. Core Templates
Template 1  Kahns Algorithm
vector<int> topoSort(int n, vector<vector<int>>& edges) {
vector<vector<int>> graph(n);
vector<int> indegree(n, 0);
for (auto& edge : edges) {
int u = edge[0];
int v = edge[1];
graph[u].push_back(v);
indegree[v]++;
}
queue<int> q;
for (int node = 0; node < n; node++) {
if (indegree[node] == 0) {
q.push(node);
}
}
vector<int> order;
while (!q.empty()) {
int node = q.front();
q.pop();
order.push_back(node);
for (int neighbor : graph[node]) {
indegree[neighbor]--;
if (indegree[neighbor] == 0) {
q.push(neighbor);
}

}
}
if (order.size() != n) {
return {};
}
return order;
}
