vector<vector<int>>& graph,
vector<int>& state) {
if (state[node] == 1) {
return true;
}
if (state[node] == 2) {
return false;
}
state[node] = 1;
for (int neighbor : graph[node]) {
if (hasCycle(neighbor, graph, state)) {

