vector<int>& state,
vector<int>& order) {
if (state[node] == 1) {
return false;
}
if (state[node] == 2) {
return true;
}
state[node] = 1;
for (int neighbor : graph[node]) {
if (!dfs(neighbor, graph, state, order)) {
return false;
}
}
state[node] = 2;
order.push_back(node);
return true;
}
