DSU Class
class DSU {
public:
vector<int> parent;
vector<int> size;
int components;

DSU(int n) {
parent.resize(n);
size.resize(n, 1);
components = n;
for (int i = 0; i < n; i++) {
parent[i] = i;
}
}
int find(int x) {
if (parent[x] != x) {
parent[x] = find(parent[x]);
}
return parent[x];
}
bool unite(int a, int b) {
int rootA = find(a);
int rootB = find(b);
if (rootA == rootB) {
return false;
}
if (size[rootA] < size[rootB]) {
swap(rootA, rootB);
}
parent[rootB] = rootA;
size[rootA] += size[rootB];
components--;
return true;
}
bool connected(int a, int b) {
return find(a) == find(b);
}
};

