vector<int> dijkstra(int n,
vector<vector<pair<int, int>>>& graph,
int source) {
const int INF = 1e9;
vector<int> dist(n, INF);
dist[source] = 0;
priority_queue<pair<int, int>,
vector<pair<int, int>>,
greater<pair<int, int>>> pq;
pq.push({0, source});
