vector<int> bellmanFord(int n, vector<vector<int>>& edges, int source) {
const int INF = 1e9;
vector<int> dist(n, INF);
dist[source] = 0;
for (int i = 0; i < n - 1; i++) {
vector<int> nextDist = dist;
for (auto& edge : edges) {
int u = edge[0];
int v = edge[1];
int w = edge[2];
if (dist[u] == INF) {
continue;
}
if (dist[u] + w < nextDist[v]) {
nextDist[v] = dist[u] + w;
}
}
dist = nextDist;
}
return dist;
}
