Core Templates
Template 1  Basic Sweep Line With Events
int maxOverlap(vector<vector<int>>& intervals) {
vector<pair<int, int>> events;
for (auto& interval : intervals) {
events.push_back({interval[0], +1});
events.push_back({interval[1], -1});
}
sort(events.begin(), events.end());
int active = 0;
int best = 0;
for (auto& [time, delta] : events) {
active += delta;
best = max(best, active);
}
return best;
}
This assumes half-open intervals [start, end) where end should be processed before
start at same time.
Because -1 sorts before +1, pair<int,int> sorting handles that naturally.
Template 2  Sweep Line With Map

int maxOverlap(vector<vector<int>>& intervals) {
map<int, int> events;
for (auto& interval : intervals) {
events[interval[0]]++;
events[interval[1]]--;
}
int active = 0;
int best = 0;
for (auto& [time, delta] : events) {
active += delta;
best = max(best, active);
}
return best;
}
Use this when coordinates are sparse or updates are dynamic.
Template 3  Closed Interval Sweep
For closed intervals [start, end], if using integer coordinates and you want intervals
ending at end to remain active at end, then one common difference-array style is:
events[start]++;
events[end + 1]--;
But this only works safely when coordinates are integer and end + 1 is meaningful.
For general coordinate sweep, handle ties manually.
Template 4  Active Interval Heap
sort(intervals.begin(), intervals.end());
priority_queue<int, vector<int>, greater<int>> minHeap;
for (auto& interval : intervals) {
int start = interval[0];
int end = interval[1];
while (!minHeap.empty() && minHeap.top() <= start) {
minHeap.pop();
}

minHeap.push(end);
}
Used when active intervals expire by end time.
Template 5  Dynamic Calendar Sweep
map<int, int> events;
bool book(int start, int end) {
events[start]++;
events[end]--;
int active = 0;
for (auto& [time, delta] : events) {
active += delta;
if (active >= 3) {
events[start]--;
events[end]++;
if (events[start] == 0) {
events.erase(start);
}
if (events[end] == 0) {
events.erase(end);
}
return false;
}
}
return true;
}
Used in My Calendar II.

