41. Mini Problem 1  N-th
Tribonacci Number
class Solution {
public:
int tribonacci(int n) {
if (n == 0) {
return 0;
}
if (n <= 2) {
return 1;
}
int a = 0;
int b = 1;
int c = 1;
for (int i = 3; i <= n; i++) {
int d = a + b + c;
a = b;
b = c;
c = d;
}
return c;
}
};
Pattern:
dp[i] = dp[i - 1] + dp[i - 2] + dp[i - 3]
42. Mini Problem 2  Perfect
Squares
class Solution {
public:
int numSquares(int n) {
vector<int> dp(n + 1, 1e9);
dp[0] = 0;

for (int i = 1; i <= n; i++) {
for (int square = 1; square * square <= i; square++) {
dp[i] = min(dp[i], dp[i - square * square] + 1);
}
}
return dp[n];
}
};
Pattern:
minimum count to form amount
Similar to Coin Change.
43. Mini Problem 3  Unique Paths
Space Optimized
class Solution {
public:
int uniquePaths(int m, int n) {
vector<int> dp(n, 1);
for (int r = 1; r < m; r++) {
for (int c = 1; c < n; c++) {
dp[c] += dp[c - 1];
}
}
return dp[n - 1];
}
};
Pattern:
dp[c] = from top + from left
44. Mini Problem 4  House
Robber II Preview
Circular houses.
Cannot rob first and last together.

Solve twice:
79.
rob houses 0..n-2
80.
rob houses 1..n-1
class Solution {
public:
int robLinear(vector<int>& nums, int left, int right) {
int prev2 = 0;
int prev1 = 0;
for (int i = left; i <= right; i++) {
int curr = max(prev1, prev2 + nums[i]);
prev2 = prev1;
prev1 = curr;
}
return prev1;
}
int rob(vector<int>& nums) {
int n = nums.size();
if (n == 1) {
return nums[0];
}
return max(robLinear(nums, 0, n - 2),
robLinear(nums, 1, n - 1));
}
};
