7. Core Template 2  Expand
Around Center
Every palindrome has a center.
For odd-length palindrome:
center at one character
Example:
racecar
   e
For even-length palindrome:
center between two characters
Example:
abba
 bb
Template:
int expand(string& s, int left, int right) {
    int count = 0;

    while (left >= 0 && right < s.size() && s[left] == s[right]) {
        count++;
        left--;
        right++;
    }

    return count;
}
Call for each center:
expand(s, i, i);       // odd
expand(s, i, i + 1);   // even

8. Core Template 3  Palindrome DP
Table
vector<vector<bool>> buildPalindromeTable(string s) {
    int n = s.size();

    vector<vector<bool>> isPal(n, vector<bool>(n, false));

    for (int len = 1; len <= n; len++) {
        for (int l = 0; l + len - 1 < n; l++) {
            int r = l + len - 1;

            if (s[l] == s[r]) {
                if (len <= 2 || isPal[l + 1][r - 1]) {
                    isPal[l][r] = true;
                }
            }
        }
    }

    return isPal;
}
Used when you need many palindrome checks.

