Palindromic Subsequence
for (int len = 1; len <= n; len++) {
    for (int l = 0; l + len - 1 < n; l++) {
        int r = l + len - 1;

        if (l == r) {
            dp[l][r] = 1;
        } else if (s[l] == s[r]) {
            dp[l][r] = 2 + dp[l + 1][r - 1];
        } else {
            dp[l][r] = max(dp[l + 1][r], dp[l][r - 1]);

        }
    }
}

