14. Full Problem Walkthrough 1
Rabin-Karp Pattern Matching
14.1 Problem Summary
Find the first occurrence of pattern in text.
Example:
text = "hello"
pattern = "ll"
Answer:
2
14.2 Idea
Compute hash of pattern.
Compute hash of every text substring of same length.
If hash matches, verify substring to avoid collision.
14.3 C++ Code
class Solution {
public:
    static const long long MOD = 1000000007;
    static const long long BASE = 911382323;

    int rabinKarp(string text, string pattern) {
        int n = text.size();
        int m = pattern.size();

        if (m > n) {
            return -1;
        }

        vector<long long> power(n + 1, 1);
        vector<long long> prefix(n + 1, 0);

        for (int i = 0; i < n; i++) {
            power[i + 1] = power[i] * BASE % MOD;
            prefix[i + 1] = (prefix[i] * BASE + text[i]) % MOD;
        }

        long long patternHash = 0;

        for (char c : pattern) {
            patternHash = (patternHash * BASE + c) % MOD;
        }

        auto getHash = [&](int l, int r) {
            long long h = prefix[r] - prefix[l] * power[r - l] %

MOD;

            if (h < 0) {
                h += MOD;
            }

            return h;
        };

        for (int i = 0; i + m <= n; i++) {
            if (getHash(i, i + m) == patternHash) {
                if (text.substr(i, m) == pattern) {
                    return i;
                }
            }
        }

        return -1;
    }
};
14.4 Complexity
Expected:
O(n + m)
Worst-case with many collisions and verification:
O(nm)
Double hashing reduces collision risk.

15. Full Problem Walkthrough 2
LeetCode 187: Repeated DNA
Sequences
15.1 Problem Summary
Given DNA string containing:
A, C, G, T
Find all 10-letter-long sequences that occur more than once.
15.2 Approach
Since length is fixed at 10, use hash set.
Could use string directly or rolling hash.
We show simple encoding because DNA has only 4 chars.
15.3 2-bit Encoding
Map:

A -> 0
C -> 1
G -> 2
T -> 3
Each char uses 2 bits.
10 chars use 20 bits.
15.4 C++ Code
class Solution {
public:
    int code(char c) {
        if (c == 'A') {
            return 0;
        }

        if (c == 'C') {
            return 1;
        }

        if (c == 'G') {
            return 2;
        }

        return 3;
    }

    vector<string> findRepeatedDnaSequences(string s) {
        vector<string> result;

        if (s.size() < 10) {
            return result;
        }

        unordered_set<int> seen;
        unordered_set<int> repeated;

        int hash = 0;
        int mask = (1 << 20) - 1;

        for (int i = 0; i < s.size(); i++) {
            hash = ((hash << 2) | code(s[i])) & mask;

            if (i >= 9) {
                if (seen.count(hash) && !repeated.count(hash)) {
                    result.push_back(s.substr(i - 9, 10));
                    repeated.insert(hash);
                }

                seen.insert(hash);

            }
        }

        return result;
    }
};
