8.3 C++ Code
class Logger {
private:
unordered_map<string, int> lastPrinted;
public:
Logger() {
}
bool shouldPrintMessage(int timestamp, string message) {
if (!lastPrinted.count(message)) {
lastPrinted[message] = timestamp;
return true;
}
if (timestamp - lastPrinted[message] >= 10) {
lastPrinted[message] = timestamp;
return true;
}
return false;
}
};
