9. Full Problem Walkthrough 2
Hit Counter
9.1 Problem Summary
Design hit counter.

API:
void hit(int timestamp);
int getHits(int timestamp);
Return hits in past 300 seconds.
9.2 Queue Approach
Store timestamps of hits.
On query, remove timestamps older than 300 seconds.
9.3 C++ Code
class HitCounter {
private:
queue<int> q;
public:
HitCounter() {
}
void hit(int timestamp) {
q.push(timestamp);
}
int getHits(int timestamp) {
while (!q.empty() && q.front() <= timestamp - 300) {
q.pop();
}
return q.size();
}
};
9.4 Complexity
Amortized:
hit: O(1)
getHits: O(1) amortized
Space:
O(number of hits in last 300 seconds)
9.5 High-Volume Version
Use 300 buckets:
class HitCounter {
private:
vector<int> times;
vector<int> counts;

public:
HitCounter() {
times.assign(300, 0);
counts.assign(300, 0);
}
void hit(int timestamp) {
int index = timestamp % 300;
if (times[index] != timestamp) {
times[index] = timestamp;
counts[index] = 1;
} else {
counts[index]++;
}
}
int getHits(int timestamp) {
int total = 0;
for (int i = 0; i < 300; i++) {
if (timestamp - times[i] < 300) {
total += counts[i];
}
}
return total;
}
};

